public class Main {
    public static void main(String[] args) {
        Account a = new Account(100);
        a.withdraw(50);
        a.withdraw(80);
        System.out.println(a.getBalance());
    }
}

class Account {
    private int balance;

    Account(int opening) {
        balance = opening;
    }

    void withdraw(int amount) {
        if (amount > 0 && amount <= balance) {
            balance -= amount;
        }
    }

    int getBalance() {
        return balance;
    }
}
